(()=>{'use strict';const B=ExamBank,C=ExamCore,M=MockCore,P=PlanCore,root=document.querySelector('#revisionPlan'),key='science-studio-plan-v1';const Q=s=>root.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={version:1,source:'latest',minutes:15,plans:{},pending:null},notice='Progress stays in this browser; it does not sync across devices.';
try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw?.version===1){state.source=typeof raw.source==='string'?raw.source:'latest';state.minutes=[15,30,45].includes(raw.minutes)?raw.minutes:15;for(const [id,plan] of Object.entries(raw.plans||{})){if(!plan||typeof plan!=='object')continue;const clean={topics:{}};for(const t of B.topics){const r=plan.topics?.[t.id]||{};clean.topics[t.id]={model:r.model===true,written:r.written===true,quiz:r.quiz&&Number.isInteger(r.quiz.score)&&r.quiz.score>=0&&r.quiz.score<=4?{score:r.quiz.score,at:Number(r.quiz.at)||0}:null};}state.plans[id]=clean;}if(raw.pending&&typeof raw.pending.attemptId==='string'&&B.topics.some(t=>t.id===raw.pending.topic))state.pending=raw.pending;}}catch(e){notice='Saved plan progress could not be read. A new plan can be created from saved mock results.';}
function save(){try{localStorage.setItem(key,JSON.stringify(state));notice='Revision-plan progress saved in this browser.';}catch(e){notice='Browser storage is unavailable or full. Plan progress is kept only for this session.';}if(Q('#planSave'))Q('#planSave').textContent=notice;}
function sources(){try{return P.attempts(B,JSON.parse(localStorage.getItem('science-studio-mocks-v1')||'null'),C,M)}catch(e){return []}}
function selected(){const list=sources();return {list,a:state.source==='latest'?list[0]:list.find(a=>a.id===state.source)||list[0]};}
function ensure(a){if(!state.plans[a.id]){state.plans[a.id]={topics:{}};save();}return state.plans[a.id];}
const labels={motion:'Forces, acceleration and coasting',evolution:'Selection across generations',atoms:'Electron shells and periodic patterns',reactions:'Balancing equations',immunity:'Immune response and memory',genetics:'Meiosis and chromosome counts',rates:'Temperature and reaction rates',heat:'Conduction, convection and radiation'};
function render(){const {list,a}=selected();root.innerHTML=`<div class="sectionhead"><div><div class="eyebrow">06 / YOUR REVISION PLAN</div><h2>Turn your results into next steps.</h2></div><span class="pill">PERSONALISED FROM YOUR MOCK</span></div><p>Focus on the evidence from one completed mock. The plan updates when written marking changes. A completed task records practice, not proof of mastery.</p><div id="planBody"></div>`;if(!a){Q('#planBody').innerHTML='<div class="planempty"><h3>Start with a mock result</h3><p>Complete a Core or Extension mock in this browser to build your plan. An unfinished attempt is not used to judge weak areas.</p><a href="#mockExams" class="button">Go to mock exams →</a></div>';return;}const items=P.build(B,a,C,M),plan=ensure(a);for(const t of items){if(t.pending&&plan.topics[t.id])plan.topics[t.id].written=false;}const weak=items.filter(t=>t.weak),pending=items.filter(t=>t.pending),done=weak.reduce((n,t)=>n+P.completion(plan.topics[t.id]),0),total=weak.length*3,session=P.session(items,plan.topics,state.minutes);Q('#planBody').innerHTML=`<div class="plantools"><label for="planSource">Use mock result<select id="planSource"><option value="latest">Latest completed mock (updates automatically)</option>${list.map(x=>`<option value="${esc(x.id)}">${M.settings[x.kind].title} · ${new Date(x.startedAt).toLocaleString('en-AU')}</option>`).join('')}</select></label><label for="planMinutes">Session length<select id="planMinutes"><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="45">45 minutes</option></select></label></div><p class="small">Based on ${M.settings[a.kind].title}, ${new Date(a.startedAt).toLocaleString('en-AU')}. Each topic was sampled by only two questions. Written evidence is self-assessed; blanks score zero.</p><div class="examdashboard"><div><b>${weak.length}</b><span>topics with recorded gaps</span></div><div><b>${done}/${total}</b><span>revision steps completed</span></div><div><b>${weak.filter(t=>P.completion(plan.topics[t.id])===3).length}/${weak.length}</b><span>topic revision cycles complete</span></div><div><b>${pending.length}</b><span>written responses awaiting marking</span></div></div><progress class="planprogress" max="${Math.max(1,total)}" value="${done}" aria-label="Completed revision steps"></progress><p id="planSave" class="small" role="status">${esc(notice)}</p>${pending.length?`<div class="planpending"><h3>Mark these responses before drawing conclusions</h3><p>${pending.map(t=>esc(t.title)).join(', ')}. Unmarked writing is not counted as a weakness. A wrong auto answer can still create a provisional task.</p><button id="planMark">Open this mock’s marking guide →</button></div>`:''}<div class="plansession"><div class="eyebrow">YOUR NEXT SESSION</div><h3>${session.topics.length?session.minutes+' minutes of focused practice':weak.length?'Revision tasks completed':'No recorded gaps in the marked answers'}</h3><p>${session.topics.length?session.topics.map(id=>esc(B.topics.find(t=>t.id===id).title)).join(' → '):pending.length?'Finish marking the pending written responses, then review the updated plan.':'Take another mock later without the guides to check retention and reveal any remaining gaps.'}</p><p class="small">Allow about five minutes per remaining step. Session lengths are estimates; take longer where you need it.</p><a href="#mockExams">Return to mock exams →</a></div><div id="planTasks">${weak.map(t=>card(t,plan.topics[t.id]||{},session.topics.includes(t.id))).join('')}</div>${items.filter(t=>!t.weak&&!t.pending).length?`<details class="planmaintain"><summary>Maintain your stronger topics</summary><p>${items.filter(t=>!t.weak&&!t.pending).map(t=>esc(t.title)).join(', ')}.</p><p>These sampled answers earned full marks. Revisit them in a later mock; this is not a claim that the whole topic is mastered.</p></details>`:''}<p class="small">Each mock has its own revision record. Choosing a newer result starts a separate plan; choosing an older result restores its check-offs. Quiz completion requires a fresh linked attempt scoring at least 3/4.</p>`;Q('#planSource').value=list.some(x=>x.id===state.source)?state.source:'latest';Q('#planMinutes').value=String(state.minutes);Q('#planSource').onchange=e=>{state.source=e.target.value;save();render()};Q('#planMinutes').onchange=e=>{state.minutes=Number(e.target.value);save();render()};if(Q('#planMark'))Q('#planMark').onclick=()=>window.dispatchEvent(new CustomEvent('science-mock-review',{detail:a.id}));wire(a,plan);}
function card(t,r,inSession){const completed=P.completion(r);return `<article class="plantopic ${inSession?'insession':''}" data-plan-topic="${t.id}"><div class="planheading"><h3>${esc(t.title)}</h3><span class="pill">${t.priority}${inSession?' · NEXT SESSION':''}</span></div><p class="small">Mock evidence: auto ${t.auto}/${t.autoTotal}; written ${t.pending?'awaiting marking':t.written+'/'+t.writtenTotal}${t.pending?' — this priority uses only the auto question':''}. ${completed}/3 revision steps complete.</p>${t.auto<t.autoTotal?'<p>Revisit the auto-question feedback and explain why the correct answer follows from the science.</p>':''}${t.missing.length?`<details><summary>Written marking points to focus on</summary><ul>${t.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}<ol class="plansteps"><li><b>Explore the model · about 5 min</b><p>${esc(labels[t.id])}. Predict a change, test it, then explain what happened.</p><button data-plan-model="${t.id}">Open animation / visual model →</button><label><input type="checkbox" data-plan-check="${t.id}" data-step="model" ${r.model?'checked':''}> I tested the model and can explain the result.</label></li><li><b>Retry the topic quiz · about 5 min</b><p>${r.quiz?`Latest linked retry: ${r.quiz.score}/4. ${r.quiz.score>=3?'Target met.':'Review the feedback and try again.'}`:'Complete all four auto questions in a fresh run. Aim for at least 3/4.'}</p><button data-plan-quiz="${t.id}">Start a fresh quiz retry →</button><span class="planstatus">${r.quiz?.score>=3?'✓ Completed automatically from your quiz result':'○ Waiting for a completed retry scoring 3/4 or better'}</span></li><li><b>Explain it again · about 5 min</b><p>${t.pending?'Mark the mock response first, then identify and revise any missing reasoning.':'Rewrite the explanation for the missed marking points. If only the auto question was wrong, explain its correct reasoning in your own words.'}</p><button data-plan-written="${t.id}">Open topic questions & marking guides →</button><label><input type="checkbox" data-plan-check="${t.id}" data-step="written" ${r.written?'checked':''} ${t.pending?'disabled':''}> I revised the reasoning and checked it against the guide.</label></li></ol></article>`;}
function wire(a,plan){root.querySelectorAll('[data-plan-check]').forEach(e=>e.onchange=()=>{const id=e.dataset.planCheck;plan.topics[id]??={};plan.topics[id][e.dataset.step]=e.checked;save();render();Q(`[data-plan-check="${id}"][data-step="${e.dataset.step}"]`)?.focus({preventScroll:true});});root.querySelectorAll('[data-plan-model]').forEach(b=>b.onclick=()=>window.dispatchEvent(new CustomEvent('science-model-topic',{detail:b.dataset.planModel})));root.querySelectorAll('[data-plan-quiz]').forEach(b=>b.onclick=()=>{state.pending={attemptId:a.id,topic:b.dataset.planQuiz,startedAt:Date.now()};save();window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:{topic:b.dataset.planQuiz,fresh:true}}));});root.querySelectorAll('[data-plan-written]').forEach(b=>b.onclick=()=>window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:b.dataset.planWritten})));}
window.addEventListener('science-quiz-completed',e=>{const x=e.detail,p=state.pending;if(!p||p.topic!==x.topic||!state.plans[p.attemptId]||!Number.isInteger(x.score)||x.score<0||x.score>4)return;const plan=state.plans[p.attemptId];plan.topics[p.topic]??={};plan.topics[p.topic].quiz={score:x.score,at:Date.now()};state.pending=null;save();render();});window.addEventListener('science-mock-updated',render);window.addEventListener('science-plan-open',e=>{if(typeof e.detail==='string'&&sources().some(x=>x.id===e.detail)){state.source=e.detail;save();}render();root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});window.addEventListener('storage',e=>{if(e.key==='science-studio-mocks-v1')render()});render();
})();
